<?php
/* Phase 316: retry Bosch image attachment after product records exist. */
add_action('init',function(){
if(get_option('bhc_catalog_image_bosch_remediation_repair_v316'))return;
@ini_set('memory_limit','768M');$map=['SMS4HMC65M'=>'bosch-sms4hmc65m-source.png','SMS4HMI25M'=>'bosch-sms4hmi25m-source.png','SMV4HAX09E'=>'bosch-smv4hax09e-source.png','SMS6ZCI16E'=>'bosch-sms6zci16e-source.png','BGS7RCL'=>'bosch-bgs7rcl-source.png'];$result=[];
foreach($map as $model=>$srcname){$ids=get_posts(['post_type'=>'product','post_status'=>'any','posts_per_page'=>1,'fields'=>'ids','meta_key'=>'_bhc_model','meta_value'=>$model]);$id=$ids?(int)$ids[0]:0;$src=__DIR__.'/'.$srcname;$rel='bhc-image-references/bosch-'.sanitize_title($model).'-repair-v316.png';$file=ABSPATH.'wp-content/uploads/'.$rel;$ok=false;$aid=0;if($id&&is_readable($src)){$im=@imagecreatefrompng($src);if($im){wp_mkdir_p(dirname($file));$w=imagesx($im);$h=imagesy($im);$scale=4096/max($w,$h);$nw=max(1,(int)round($w*$scale));$nh=max(1,(int)round($h*$scale));$c=imagecreatetruecolor($nw,$nh);imagealphablending($c,false);imagesavealpha($c,true);$z=imagecolorallocatealpha($c,0,0,0,127);imagefill($c,0,0,$z);imagecopyresampled($c,$im,0,0,0,0,$nw,$nh,$w,$h);imagepng($c,$file,6);imagedestroy($c);imagedestroy($im);$ok=is_readable($file);}}if($ok){$old=get_post_thumbnail_id($id);if($old)wp_delete_attachment($old,true);$aid=wp_insert_attachment(['post_mime_type'=>'image/png','post_title'=>'Bosch '.$model.' اختصاصی 4K شفاف','post_status'=>'inherit','post_parent'=>$id],$file,$id);if($aid&&!is_wp_error($aid)){update_post_meta($aid,'_wp_attached_file',$rel);$q=@getimagesize($file);wp_update_attachment_metadata($aid,['width'=>$q[0]??4096,'height'=>$q[1]??4096,'file'=>$rel,'sizes'=>[]]);set_post_thumbnail($id,$aid);update_post_meta($id,'_bhc_image_generation_status','product_specific_generated');update_post_meta($id,'_bhc_image_status','generated_4k_transparent_verified');update_post_meta($id,'_bhc_image_long_edge',max((int)($q[0]??0),(int)($q[1]??0)));update_post_meta($id,'_bhc_image_featured_verified','yes');}}$result[$model]=['id'=>$id,'ok'=>$ok,'attachment'=>$aid,'exists'=>is_readable($file)];}
update_option('bhc_catalog_image_bosch_remediation_repair_v316',['result'=>$result,'at'=>current_time('mysql')],false);
},316);
